PASTA = "/var/www/uploads"

@app.post("/perfil/avatar")
def enviar_avatar(arquivo: UploadFile, usuario = Depends(sessao)):
    if not arquivo.content_type.startswith("image/"):
        raise HTTPException(422, "envie uma imagem")

    destino = os.path.join(PASTA, arquivo.filename)
    with open(destino, "wb") as saida:
        saida.write(arquivo.file.read())

    usuario.avatar_url = f"/uploads/{arquivo.filename}"
    repo.salvar(usuario)
    return {"url": usuario.avatar_url}

