@app.middleware("http")
async def registrar(requisicao, seguir):
    resposta = await seguir(requisicao)
    log.info(
        "requisicao",
        extra={
            "caminho": str(requisicao.url),
            "cabecalhos": dict(requisicao.headers),
            "status": resposta.status_code,
        },
    )
    return resposta

def baixar_estoque(produto_id, quantidade):
    atual = repo.quantidade_de(produto_id)

    if atual < quantidade:
        raise SemEstoque(produto_id)

    repo.atualizar_quantidade(produto_id, atual - quantidade)

def quantidade_de(produto_id):
    return db.query("SELECT quantidade FROM estoque WHERE produto_id = %s", produto_id)

def atualizar_quantidade(produto_id, nova):
    db.execute("UPDATE estoque SET quantidade = %s WHERE produto_id = %s", nova, produto_id)

@app.get("/relatorios/fechamento.csv")
def exportar(mes: str):
    pedidos = repo.listar_do_mes(mes)   # devolve lista completa

    linhas = []
    for pedido in pedidos:
        cliente = repo.cliente_de(pedido.cliente_id)
        linhas.append(f"{pedido.id};{cliente.nome};{pedido.total};{pedido.criado_em}")

    corpo = "\n".join(linhas)
    return Response(corpo, media_type="text/csv")

